/* mdview KaTeX stub — real katex.min.js is downloaded at build time by build.rs.
   This stub provides a minimal `renderMathInElement` so tests pass offline. */
(function (root, factory) {
  if (typeof module === "object" && module.exports) module.exports = factory();
  else root.katex = factory(), root.renderMathInElement = root.katex.renderMathInElement;
})(typeof self !== "undefined" ? self : this, function () {
  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c];
    });
  }
  function renderNode(tex, display) {
    var el = document.createElement(display ? "div" : "span");
    el.className = "katex" + (display ? " katex-display" : "");
    el.setAttribute("data-tex", tex);
    el.textContent = tex;
    return el;
  }
  function renderMathInElement(rootEl, options) {
    if (!rootEl) return;
    var sel = ".mdv-math, .mdv-math-block";
    var nodes = rootEl.querySelectorAll(sel);
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i];
      if (n.getAttribute("data-mdv-rendered") === "1") continue;
      var tex = n.getAttribute("data-tex") || n.textContent;
      var isBlock = n.classList.contains("mdv-math-block");
      var rendered = renderNode(tex, isBlock);
      n.innerHTML = "";
      n.appendChild(rendered);
      n.setAttribute("data-mdv-rendered", "1");
    }
  }
  return {
    render: function (tex, el, opts) {
      el.appendChild(renderNode(tex, !!(opts && opts.displayMode)));
    },
    renderToString: function (tex) {
      return '<span class="katex">' + escapeHtml(tex) + "</span>";
    },
    renderMathInElement: renderMathInElement
  };
});
